// Generate an expression string (1-4096 bytes, may include non-printables)
std::string expr = FUZZ_PARAM_STR();
// Randomly decide whether to provide an error pointer or NULL
unsigned int choose_err = *FUZZ_PARAM(unsigned int);
te_int_t err_storage = 0;
te_int_t *errp = (choose_err & 1) ? &err_storage : (te_int_t *)0;
// Ensure null-terminated C string is passed
const char *c_expr = expr.c_str();
// Call te_interp; it returns NaN on error per API contract
volatile double result = te_interp(c_expr, errp);
(void)result;
// Validation: expression is null-terminated; error pointer is either NULL or valid storage.

// Prepare an input expression
std::string expr_str = FUZZ_PARAM_STR();
const char *c_expr = expr_str.c_str();
// Decide on variable bindings: 0..3 variables
unsigned int selector = *FUZZ_PARAM(unsigned int);
int var_count = (int)(selector % 4);
// Prepare up to 3 variable bindings with simple ASCII names and double storage
// Names chosen to be valid identifiers to increase chance of binding
const char *names[3] = {"a", "b", "c"};
// Double storage for variables
double vals_buf[3] = { *FUZZ_PARAM(double), *FUZZ_PARAM(double), *FUZZ_PARAM(double) };
// Build te_variable array locally
te_variable vars_local[3];
for (int i = 0; i < 3; ++i) {
    vars_local[i].name = names[i];
    vars_local[i].address = (const void *)&vals_buf[i];
    vars_local[i].type = TE_VARIABLE; // variable binding
    vars_local[i].context = (void *)0; // no context for plain variables
}
// variables pointer is NULL if var_count == 0 per API requirement
const te_variable *vars_ptr = (var_count > 0) ? (const te_variable *)vars_local : (const te_variable *)0;
// Randomly decide whether to request error reporting
te_int_t err_storage = 0;
te_int_t *errp = (selector & 0x2) ? &err_storage : (te_int_t *)0;
// Compile the expression
te_expr *expr = te_compile(c_expr, vars_ptr, var_count, errp);
// Must succeed to produce a te_expr*; otherwise bail for this attempt
if (!expr) { FUZZ_BAIL(); }
// Mark the object as a compiled tinyexpr node for downstream stubs
FUZZ_SET_ATTR_INT(expr, "compiled", 1);
FUZZ_SET_ATTR_INT(expr, "var_count", var_count);
// Validation: If returned non-NULL, expr must be freed later with te_free and is marked compiled.

// Ensure this te_expr* was produced by te_compile
int compiled = FUZZ_GET_ATTR_INT(expr, "compiled");
if (!compiled) { FUZZ_BAIL(); }
// Evaluate; result may be any double (including NaN) depending on expression
volatile double value = te_eval((const te_expr *)expr);
(void)value;
// Return expr back to the pool for further use (still compiled and owned by API)
// Validation: Input non-NULL and marked compiled; object preserved for later freeing.

// te_print expects a previously compiled expression
int compiled = FUZZ_GET_ATTR_INT(expr, "compiled");
if (!compiled) { FUZZ_BAIL(); }
// Print debug info (to stdout/stderr depending on implementation)
te_print((const te_expr *)expr);
// Keep expr alive for subsequent stubs
// Validation: Only operates on compiled expressions; no ownership transfer.

// te_free may be called with NULL, but our runtime provides non-NULL inputs.
// Enforce that this te_expr was previously returned by te_compile
int compiled = FUZZ_GET_ATTR_INT(expr, "compiled");
if (!compiled) { FUZZ_BAIL(); }
// Free and drop from pool to avoid use-after-free
te_free((te_expr *)expr);
// Validation: Frees only objects known to be compiled by tinyexpr; object not returned to pool.

// Simple inline getter; exercise the call path
volatile unsigned cp = te_cp();
(void)cp;
// Validation: Trivial call with no side effects or constraints.

// Simple inline getter; exercise the call path
volatile unsigned inv = te_invalid_chr();
(void)inv;
// Validation: Trivial call with no side effects or constraints.

// Optionally pass NULL per API; otherwise a string starting at some character
unsigned int sel = *FUZZ_PARAM(unsigned int);
const char *p = (sel & 1) ? (const char *)0 : FUZZ_PARAM_STR().c_str();
volatile unsigned isnum = te_is_num((const char * const)p);
(void)isnum;
// Validation: Covers both NULL and non-NULL paths.

// Optionally pass NULL per API; otherwise pass a random string
unsigned int sel = *FUZZ_PARAM(unsigned int);
const char *p = (sel & 1) ? (const char *)0 : FUZZ_PARAM_STR().c_str();
volatile int isop = te_is_op((const char * const)p);
(void)isop;
// Validation: Covers both NULL and non-NULL paths including operator/non-operator cases.

