import random
import math
from typing import List, Tuple

# Generator for tinyexpr-compatible mathematical expression strings.
# Focus: produce valid, diverse, null-terminated strings with optional variables a,b,c
# and functions/operators tinyexpr typically supports.
# Size capped to <= 4096 bytes.

FUNCTIONS_1 = [
    "sin", "cos", "tan", "asin", "acos", "atan",
    "sqrt", "log", "log10", "abs", "floor", "ceil",
    "exp", "sign", "round"
]

FUNCTIONS_2 = [
    "pow", "min", "max", "atan2"
]

CONSTANTS = [
    "pi", "e"
]

VARS = ["a", "b", "c"]

UNARY_PREFIX = ["+", "-", "+", "-", "~"]  # ~ may not exist; include occasionally
BINARY_OPS = ["+", "-", "*", "/", "%", "^"]
COMPARISON_OPS = ["<", ">", "<=", ">=", "==", "!="]
LOGICAL_OPS = ["&&", "||"]

WHITESPACE = [" ", "\t", "  ", "\n"]

DIGITS = "0123456789"
IDENT_START = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
IDENT_CONT = IDENT_START + DIGITS

MAX_LEN = 4096


def _rand_ws(r: random.Random) -> str:
    if r.random() < 0.5:
        return ""
    return r.choice(WHITESPACE)


def _rand_number(r: random.Random) -> str:
    # Generate integers, decimals, scientific notation, with optional unary sign
    sign = r.choice(["", "+", "-"])
    kind = r.random()
    if kind < 0.4:
        # integer
        n = str(r.randrange(0, 10**(r.randint(1, 6))))
        return sign + n
    elif kind < 0.8:
        # decimal
        int_part = str(r.randrange(0, 10**(r.randint(0, 4))))
        frac_part = str(r.randrange(0, 10**(r.randint(1, 6)))).rjust(r.randint(1, 6), "0")
        if int_part == "":
            int_part = "0"
        return f"{sign}{int_part}.{frac_part}"
    else:
        # scientific notation
        base = _rand_number_simple_decimal(r)
        exp_sign = r.choice(["+", "-"])
        exp_val = str(r.randint(0, 308))
        return f"{sign}{base}e{exp_sign}{exp_val}"


def _rand_number_simple_decimal(r: random.Random) -> str:
    int_part = str(r.randrange(0, 10**(r.randint(0, 3))))
    frac_len = r.randint(0, 5)
    if frac_len == 0:
        return int_part if int_part else "0"
    frac_part = ''.join(r.choice(DIGITS) for _ in range(frac_len))
    if not int_part:
        int_part = "0"
    return f"{int_part}.{frac_part}"


def _rand_identifier(r: random.Random) -> str:
    # Prefer variables/functions/constants known to tinyexpr
    choice = r.random()
    if choice < 0.4:
        return r.choice(VARS)
    elif choice < 0.7:
        return r.choice(CONSTANTS)
    elif choice < 0.85:
        return r.choice(FUNCTIONS_1)
    elif choice < 0.95:
        return r.choice(FUNCTIONS_2)
    # otherwise arbitrary identifier
    l = r.randint(1, 8)
    s = r.choice(IDENT_START)
    s += ''.join(r.choice(IDENT_CONT) for _ in range(l-1))
    return s


def _maybe_unary(r: random.Random) -> str:
    if r.random() < 0.35:
        # allow chains like --+ occasionally
        reps = 1 if r.random() < 0.8 else r.randint(2, 3)
        return ''.join(r.choice(UNARY_PREFIX) for _ in range(reps))
    return ""


def _atom(r: random.Random, depth: int) -> str:
    # Atoms: number, variable/constant, parenthesized expr, function call
    if depth <= 0:
        return r.choice([_rand_number(r), r.choice(VARS), r.choice(CONSTANTS)])
    t = r.random()
    if t < 0.35:
        return _rand_number(r)
    elif t < 0.6:
        return r.choice(VARS)
    elif t < 0.7:
        return r.choice(CONSTANTS)
    elif t < 0.88:
        # parenthesized
        inner = _expr(r, depth-1)
        return f"({_rand_ws(r)}{inner}{_rand_ws(r)})"
    else:
        # function call
        if r.random() < 0.7:
            fname = r.choice(FUNCTIONS_1)
            arg = _expr(r, depth-1)
            return f"{fname}({_rand_ws(r)}{arg}{_rand_ws(r)})"
        else:
            fname = r.choice(FUNCTIONS_2)
            arg1 = _expr(r, depth-1)
            arg2 = _expr(r, depth-1)
            return f"{fname}({_rand_ws(r)}{arg1}{_rand_ws(r)},{_rand_ws(r)}{arg2}{_rand_ws(r)})"


def _term(r: random.Random, depth: int) -> str:
    s = _maybe_unary(r) + _atom(r, depth)
    # chain of power binds right-associative in many parsers; here just linear
    while r.random() < 0.35 and len(s) < 512:
        op = r.choice(["^"]) if r.random() < 0.5 else r.choice(["*", "/", "%"])  # bias to pow/mul
        s = f"{s}{_rand_ws(r)}{op}{_rand_ws(r)}{_maybe_unary(r)}{_atom(r, depth)}"
    return s


def _arith_expr(r: random.Random, depth: int) -> str:
    s = _term(r, depth)
    while r.random() < 0.5 and len(s) < 1024:
        op = r.choice(BINARY_OPS)
        s = f"{s}{_rand_ws(r)}{op}{_rand_ws(r)}{_term(r, depth)}"
    return s


def _rel_expr(r: random.Random, depth: int) -> str:
    s = _arith_expr(r, depth)
    if r.random() < 0.4:
        op = r.choice(COMPARISON_OPS)
        s = f"{s}{_rand_ws(r)}{op}{_rand_ws(r)}{_arith_expr(r, depth)}"
    return s


def _logic_expr(r: random.Random, depth: int) -> str:
    s = _rel_expr(r, depth)
    if r.random() < 0.3:
        # possibly chain a couple logical ops
        reps = r.randint(1, 2)
        for _ in range(reps):
            op = r.choice(LOGICAL_OPS)
            s = f"{s}{_rand_ws(r)}{op}{_rand_ws(r)}{_rel_expr(r, depth)}"
    return s


def _expr(r: random.Random, depth: int) -> str:
    return _logic_expr(r, depth)


def _maybe_trailing_ws(r: random.Random) -> str:
    return _rand_ws(r) if r.random() < 0.6 else ""


def _maybe_invalid_but_safe(r: random.Random) -> str:
    # Sometimes include valid but edge-y constructs tinyexpr handles as end or operator
    # such as empty string or single operator to exercise error paths in a controlled way.
    choice = r.random()
    if choice < 0.05:
        return ""  # empty expression
    if choice < 0.10:
        return r.choice(["+", "-", "*", "/", "(", ")"])  # minimal
    return None


def build_expression(r: random.Random) -> str:
    # Occasionally generate comma-separated expression lists if parser allows (function args generally)
    special = _maybe_invalid_but_safe(r)
    if special is not None:
        return special

    depth = r.randint(2, 5)
    base = _expr(r, depth)

    # Optionally build ternary-like structure if supported (some tinyexpr forks support ?:; vanilla usually not)
    if r.random() < 0.05:
        base = f"{_expr(r, depth-1)} ? {_expr(r, depth-1)} : {_expr(r, depth-1)}"

    # Optionally prepend unary chain
    if r.random() < 0.25:
        base = _maybe_unary(r) + base

    # Optional surrounding whitespace
    base = _maybe_trailing_ws(r) + base + _maybe_trailing_ws(r)

    # Ensure usage of variables a,b,c to match fuzzer-provided bindings
    if r.random() < 0.5 and not any(v in base for v in VARS):
        base = f"{base}{_rand_ws(r)}+{_rand_ws(r)}{r.choice(VARS)}"

    # Optional multiple subexpressions combined by comma inside a wrapper function like min/max
    if r.random() < 0.15:
        wrapper = r.choice(["min", "max", "pow", "atan2"])
        base = f"{wrapper}({_rand_ws(r)}{_expr(r, depth-1)}{_rand_ws(r)},{_rand_ws(r)}{_expr(r, depth-1)}{_rand_ws(r)})"

    return base


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Randomly choose between several expression themes
    theme = r.random()
    if theme < 0.2:
        # Trigonometric composition
        angle = build_expression(r)
        expr = f"sin({angle}) + cos({angle}) + tan({angle})"
    elif theme < 0.4:
        # Polynomial with variables
        terms = []
        nterms = r.randint(2, 5)
        for i in range(nterms):
            coef = _rand_number(r)
            var = r.choice(VARS + [""])
            powpart = f"^{r.randint(2,5)}" if var and r.random() < 0.5 else ""
            piece = f"({coef}{_rand_ws(r)}*{_rand_ws(r)}{var}{powpart})" if var else f"({coef})"
            terms.append(piece)
        expr = (f"{_rand_ws(r)}+{_rand_ws(r)}").join(terms)
    elif theme < 0.6:
        # Function nest
        expr = build_expression(r)
        for _ in range(r.randint(1, 3)):
            f1 = r.choice(FUNCTIONS_1)
            expr = f"{f1}({_rand_ws(r)}{expr}{_rand_ws(r)})"
    elif theme < 0.8:
        # Mixed arithmetic with comparisons and logicals
        a = build_expression(r)
        b = build_expression(r)
        c = build_expression(r)
        op1 = random.choice(COMPARISON_OPS)
        op2 = random.choice(LOGICAL_OPS)
        expr = f"({a}) {op1} ({b}) {op2} ({c})"
    else:
        # General expression
        expr = build_expression(r)

    # Final trim to ensure length <= 4096, and ensure null-terminated C string
    s = expr[:MAX_LEN - 1]

    # Bias to include valid identifier-only expressions too
    if len(s) == 0:
        s = r.choice(VARS + CONSTANTS + ["0", "1"])  # ensure non-empty most times

    # Return as bytes (UTF-8). The fuzzer will pass c_str() which is null-terminated in C++.
    data = s.encode('utf-8', errors='strict')
    return data
